    call    TempoBpmReloadWrite_entry, [d2], 4
    call    func_48445C98, 0, 0xc
    bra     0x48445344
    clr     d0
    cmp     1, d1
    bne     0x4844532f
    mov     1, d0
    movhu   d0, (0x5014966a)
