# DiskInit  (CPU 0x4854acdc)
#   create the disk-worker world: SdHwInit, reset the driver records
#   (0x50160654 block), phase:=1, power line+rail off, SdSlotRelease,
#   media state:=1; create+start MILK task 8 (descriptor 0x4867BE98 ->
#   DiskWorkerTask, prio 3, stack 0xC00), create mailboxes 9 (commands)
#   and 0xA (completions), clear the 10 client ctrl blocks 0x50082748..
#   0x50082928 (0x30 bytes each) and post the done-event to each
    movm    [a2], (sp)
    add     -0x10, sp
# DiskInit_entry:   (register-save `call` entry)
    call    SdHwInit_entry, 0, 8
    mov     0x50160654, a0
    call    SdDrvRecordsReset_entry, [d2], 0x10
    mov     1, d0
    movhu   d0, (0x50160658)
    call    SdPowerLineClear_entry, 0, 8
    call    SdPowerRailClear_entry, 0, 0xc
    call    SdPowerLineClear_entry, 0, 8
    call    SdPowerRailClear_entry, 0, 0xc
    call    SdSlotRelease_entry, 0, 8
    mov     1, d0
    call    SdMediaStateSet_entry, [d2], 4
    mov     8, d0
    mov     0x4867be98, a0
    call    cre_tsk, 0, 0
    mov     8, d0
    clr     d1
    call    sta_tsk, 0, 0
    mov     0x4867beac, a2
    mov     9, d0
    mov     a2, a0
    call    0x4c03bf96, 0, 0
    mov     0xa, d0
    mov     a2, a0
    call    0x4c03bf96, 0, 0
    mov     0x50082748, a2
    mov     a2, a0
    call    DiskWorkerStatusClear, 0, 0
    mov     0xa, d0
    mov     a2, a0
    call    LibMsgSend, 0, 0
    add     0x30, a2
    cmp     0x50082928, a2
    bcs     0x4854ad52
    ret     [a2], 0x14
# DiskHookNops  (CPU 0x4854ad6f)
.incbin_range "baserom/kn7000_program_sp7001.rom", 0x14ad6f, 0x14ad78
# DiskWorkerStatusClear  (CPU 0x4854ad78)
#   clear the ctrl-block status halfword (4,a0)
    clr     d0
    movhu   d0, (4, a0)
    retf    0, 0
# DiskWorkerTask  (CPU 0x4854ad7f)
#   MILK task 8 main loop: blocking-receive a 0x14-byte message from
#   mailbox 9 (LibMsgReceive), dispatch on type halfword +8: 2 ->
#   DiskDriveCtrlHandler (drive-letter control commands), 3 ->
#   SdWorkerCmdHandler (SD media commands); optional per-message
#   completion callback (calls), then clear status + post done-event 0xA
    movm    [d2,d3,a2,a3], (sp)
    add     -0x44, sp
    mov     sp, a0
    mov     a0, d3
    add     0x10, d3
    mov     a0, d2
    add     0x14, d2
    mov     8, a2
    add     d2, a2
    mov     0x10, a3
    add     a2, a3
    add     0x1c, d2
    mov     d3, a0
    mov     9, d0
    call    LibMsgReceive, 0, 0
    mov     (0x10, sp), a0
    mov     sp, a1
    add     0x14, a1
    mov     -0xc, d1
    setlb
    mov     (a0), d0
    inc4    a0
    mov     d0, (a1)
    inc4    a1
    inc     d1
    lne
    movhu   (0x18, sp), d0
    cmp     2, d0
    beq     0x4854adbd
    cmp     3, d0
    beq     0x4854add0
    bra     0x4854ade3
    mov     a2, a0
    call    DiskDriveCtrlHandler_entry, [d2,d3,a2], 0x40
    mov     (a3), d1
    cmp     0, d1
    beq     0x4854ade3
    mov     (a3), a1
    exth    d0
    mov     a2, a0
    calls   (a1)
    bra     0x4854ade3
    mov     d2, a0
    call    SdWorkerCmdHandler_entry, [d2,d3,a2,a3], 0x48
    mov     (0x40, sp), a0
    cmp     0, a0
    beq     0x4854ade3
    mov     a0, a1
    exth    d0
    mov     d2, a0
    calls   (a1)
    mov     (0x10, sp), a0
    call    DiskWorkerStatusClear, 0, 0
    mov     0xa, d0
    mov     (0x10, sp), a0
    call    LibMsgSend, 0, 0
    bra     0x4854ad97
    ret     [d2,d3,a2,a3], 0x54
# DiskCmdReplyCopy  (CPU 0x4854adfa)
#   transact completion callback (installed at ctrl+0x2C): when the
#   pending flag 0x500051B8 == 1 copy the 16-byte reply between the
#   caller buffer and the shadow 0x501606C0, result -> 0x500051BA,
#   pending := 0
